-- =====================================================================
-- Goldfinch Adventures — DEMO / PRODUCTION-PREVIEW SEED
-- Lots of realistic content so the whole system looks "full".
-- Idempotent (on conflict ... do update) and additive.
-- Run AFTER schema.sql + seed.sql (needs the base admin user + the
-- Tanzania/Kenya/Rwanda destinations + base categories).
--   psql "$DATABASE_URL" -f database/seed-demo.sql
-- Base IDs used: admin user 00000000-0000-4000-8000-000000000001;
--   destinations 101 Tanzania, 102 Kenya, 103 Rwanda;
--   categories 201 safari, 202 beach-holiday, 203 kilimanjaro.
-- =====================================================================

-- ---------- extra DESTINATIONS (so the showcase has many tabs) ----------
insert into destinations (id, name, slug, country, region, short_description, description, main_image_url, banner_image_url, status, is_featured,
  safety_overview, health_vaccinations, security_advice, travel_insurance_note, emergency_contacts,
  score_wildlife, score_luxury, score_family, score_photography, score_adventure, score_budget_from, meta_title, meta_description, created_by, updated_by)
values
  ('00000000-0000-4000-8000-000000000104', 'Uganda', 'uganda', 'Uganda', 'Bwindi & the west', 'Gorillas, chimps and classic savanna — the adventurous choice.', 'Uganda combines mountain gorilla trekking in Bwindi, chimpanzees in Kibale and big-game savanna in Queen Elizabeth NP, often in one rewarding trip.', 'https://images.unsplash.com/photo-1502784444187-359ac186c5bb', 'https://images.unsplash.com/photo-1502784444187-359ac186c5bb', 'published', true,
   'Uganda is welcoming and well-suited to adventurous travellers; gorilla and chimp treks are guided and regulated.', 'A yellow fever certificate is required. Antimalarials recommended throughout.', 'Exercise normal precautions in Kampala; the parks and lodges are secure.', 'Travel insurance with medical evacuation is required; permits are non-refundable.', 'Your guide and our 24/7 support line. Uganda emergency services: 999 / 112.',
   8, 6, 6, 8, 9, 1800, 'Uganda Gorilla & Safari Tours', 'Plan Uganda gorilla trekking, chimps and savanna safari with Goldfinch Adventures.', '00000000-0000-4000-8000-000000000001', '00000000-0000-4000-8000-000000000001'),
  ('00000000-0000-4000-8000-000000000105', 'Zanzibar', 'zanzibar', 'Tanzania', 'Indian Ocean coast', 'White-sand beaches, Stone Town and the perfect safari finale.', 'Zanzibar pairs barefoot beach time with spice tours, Stone Town history and dhow cruises — the classic way to end an East Africa safari.', 'https://images.unsplash.com/photo-1605731414532-6b26976cc153', 'https://images.unsplash.com/photo-1558998708-ce92a9c8da00', 'published', true,
   'Zanzibar is a relaxed, popular beach destination; resorts are secure and well-run.', 'Antimalarials are recommended. A yellow fever certificate may be required if arriving from an endemic country.', 'Dress modestly in Stone Town out of respect for local culture; resorts and beaches are safe.', 'Travel insurance covering water activities and medical care is recommended.', 'Your hotel and our 24/7 support line. Tanzania emergency services: 112.',
   4, 8, 8, 7, 6, 900, 'Zanzibar Beaches & Stone Town', 'Plan a Zanzibar beach escape and safari-and-beach combo with Goldfinch Adventures.', '00000000-0000-4000-8000-000000000001', '00000000-0000-4000-8000-000000000001')
on conflict (id) do update set
  name = excluded.name, slug = excluded.slug, country = excluded.country, region = excluded.region,
  short_description = excluded.short_description, description = excluded.description,
  main_image_url = excluded.main_image_url, banner_image_url = excluded.banner_image_url,
  status = excluded.status, is_featured = excluded.is_featured,
  safety_overview = excluded.safety_overview, health_vaccinations = excluded.health_vaccinations,
  security_advice = excluded.security_advice, travel_insurance_note = excluded.travel_insurance_note,
  emergency_contacts = excluded.emergency_contacts,
  score_wildlife = excluded.score_wildlife, score_luxury = excluded.score_luxury, score_family = excluded.score_family,
  score_photography = excluded.score_photography, score_adventure = excluded.score_adventure, score_budget_from = excluded.score_budget_from,
  meta_title = excluded.meta_title, meta_description = excluded.meta_description;

-- ---------- extra CATEGORIES (= Experiences / Safari Type) ----------
insert into tour_categories (id, name, slug, description, who_its_for, fitness, highlights, image_url, status, sort_order, meta_description)
values
  ('00000000-0000-4000-8000-000000000204', 'Gorilla Trekking', 'gorilla-trekking', 'Mountain gorilla and primate encounters in Rwanda and Uganda.', 'Travellers seeking a once-in-a-lifetime encounter with mountain gorillas.', 'Moderate to challenging — steep forest trekking.', array['Mountain gorilla families','Bwindi & Volcanoes NP','Limited daily permits','Pairs well with a safari'], 'https://images.unsplash.com/photo-1547471080-7cc2caa01a7e', 'published', 4, 'Plan gorilla trekking in Rwanda or Uganda with Goldfinch Adventures.'),
  ('00000000-0000-4000-8000-000000000205', 'Zanzibar Beach', 'zanzibar-beach', 'Indian Ocean beaches, Stone Town and dhow cruises.', 'Couples, honeymooners and families wanting to unwind after a safari.', 'Easy — pure relaxation.', array['White-sand beaches','Stone Town & spices','Snorkelling & dhow cruises','Safari + beach combos'], 'https://images.unsplash.com/photo-1605731414532-6b26976cc153', 'published', 5, 'Plan a Zanzibar beach holiday with Goldfinch Adventures.'),
  ('00000000-0000-4000-8000-000000000206', 'Combined Trips', 'combined-trips', 'Multi-country journeys — safari, gorillas and beach in one trip.', 'Travellers who want to see more in one seamless, well-routed itinerary.', 'Easy to moderate, depending on the mix.', array['Multi-country routing','Safari + gorillas + beach','Light-aircraft hops','One coordinated plan'], 'https://images.unsplash.com/photo-1516426122078-c23e76319801', 'published', 6, 'Plan a combined East Africa safari, gorilla and beach trip.')
on conflict (id) do update set
  name = excluded.name, slug = excluded.slug, description = excluded.description,
  who_its_for = excluded.who_its_for, fitness = excluded.fitness, highlights = excluded.highlights,
  image_url = excluded.image_url, status = excluded.status, sort_order = excluded.sort_order, meta_description = excluded.meta_description;

