values
  -- Tanzania (101)
  ('00000000-0000-4000-8000-000000000310', 'Serengeti & Ngorongoro Luxury Safari', 'serengeti-ngorongoro-luxury-safari', 'Eight days of the Serengeti, Ngorongoro Crater and a balloon sunrise — at the finest camps.', 'A flagship northern-circuit safari combining the Serengeti, Ngorongoro Crater and Tarangire, staying in luxury tented camps with private guiding throughout.', '00000000-0000-4000-8000-000000000101', '00000000-0000-4000-8000-000000000201', 'safari', array['couple','family'], 8, 7, 'luxury', 4200, 'USD', 'https://images.unsplash.com/photo-1516426122078-c23e76319801', 'https://images.unsplash.com/photo-1505765050516-f72dcac9c60e', array['Great Migration','Big Five','Balloon safari','Ngorongoro Crater','Bush dinner'], 'Easy', 2, 6, 'Kilimanjaro Airport', 'Arusha', 'published', true, true, 'Serengeti & Ngorongoro Luxury Safari', 'An 8-day luxury northern Tanzania safari with the Serengeti, Crater and a balloon flight.', '00000000-0000-4000-8000-000000000001', '00000000-0000-4000-8000-000000000001'),
  ('00000000-0000-4000-8000-000000000311', 'Tanzania Family Safari Adventure', 'tanzania-family-safari-adventure', 'A family-paced six-day safari with shorter drives and kid-friendly lodges.', 'Designed for families: Tarangire, the Serengeti and Ngorongoro at a relaxed pace, with connecting rooms and guides who love young explorers.', '00000000-0000-4000-8000-000000000101', '00000000-0000-4000-8000-000000000201', 'safari', array['family'], 6, 5, 'mid_range', 2400, 'USD', 'https://images.unsplash.com/photo-1535941339077-2dd1c7963098', null, array['Family-friendly lodges','Big cats','Maasai village','Short game drives'], 'Easy', 2, 7, 'Arusha', 'Arusha', 'published', false, true, 'Tanzania Family Safari', 'A 6-day family safari in northern Tanzania, paced for children.', '00000000-0000-4000-8000-000000000001', '00000000-0000-4000-8000-000000000001'),
  ('00000000-0000-4000-8000-000000000312', 'Tanzania Budget Camping Safari', 'tanzania-budget-camping-safari', 'Five days of classic safari on a budget, camping under the stars.', 'Great value without missing the highlights — Serengeti and Ngorongoro on a guided camping safari for adventurous travellers.', '00000000-0000-4000-8000-000000000101', '00000000-0000-4000-8000-000000000201', 'safari', array['solo','group'], 5, 4, 'budget', 1300, 'USD', 'https://images.unsplash.com/photo-1504432842672-1a79f78e4084', null, array['Serengeti plains','Ngorongoro Crater','Campfire nights','Great value'], 'Moderate', 2, 8, 'Arusha', 'Arusha', 'published', false, false, 'Tanzania Budget Camping Safari', 'A 5-day budget camping safari in northern Tanzania.', '00000000-0000-4000-8000-000000000001', '00000000-0000-4000-8000-000000000001'),
  -- Kenya (102)
  ('00000000-0000-4000-8000-000000000313', 'Masai Mara Migration Safari', 'masai-mara-migration-safari', 'Seven days chasing the Great Migration and big cats across the Mara.', 'Time your trip with the Mara River crossings and enjoy superb big-cat viewing, staying in classic tented camps in the heart of the reserve.', '00000000-0000-4000-8000-000000000102', '00000000-0000-4000-8000-000000000201', 'safari', array['couple','group'], 7, 6, 'mid_range', 2900, 'USD', 'https://images.unsplash.com/photo-1516026672322-bc52d61a55d5', 'https://images.unsplash.com/photo-1534177616072-ef7dc120449d', array['Mara River crossings','Big cats','Hot-air balloon','Maasai culture','Open plains'], 'Easy', 2, 6, 'Nairobi', 'Nairobi', 'published', true, true, 'Masai Mara Migration Safari', 'A 7-day Masai Mara safari timed for the Great Migration.', '00000000-0000-4000-8000-000000000001', '00000000-0000-4000-8000-000000000001'),
  ('00000000-0000-4000-8000-000000000314', 'Kenya Luxury Safari & Laikipia', 'kenya-luxury-safari-laikipia', 'Nine days of exclusive conservancies, rhino and the Mara in style.', 'A premium Kenya journey across Laikipia''s private conservancies and the Masai Mara, with light-aircraft hops and top-tier lodges.', '00000000-0000-4000-8000-000000000102', '00000000-0000-4000-8000-000000000201', 'safari', array['couple'], 9, 8, 'ultra_luxury', 6800, 'USD', 'https://images.unsplash.com/photo-1549366021-9f761d450615', null, array['Private conservancies','Rhino tracking','Light-aircraft transfers','Exclusive lodges'], 'Easy', 2, 4, 'Nairobi', 'Nairobi', 'published', false, true, 'Kenya Luxury Safari & Laikipia', 'A 9-day luxury Kenya safari across Laikipia and the Mara.', '00000000-0000-4000-8000-000000000001', '00000000-0000-4000-8000-000000000001'),
  ('00000000-0000-4000-8000-000000000315', 'Kenya Classic Value Safari', 'kenya-classic-value-safari', 'A great-value five-day loop through Amboseli and the Mara.', 'Amboseli''s elephants beneath Kilimanjaro plus the Masai Mara — a well-priced introduction to Kenya''s wildlife.', '00000000-0000-4000-8000-000000000102', '00000000-0000-4000-8000-000000000201', 'safari', array['solo','family'], 5, 4, 'budget', 1500, 'USD', 'https://images.unsplash.com/photo-1521651201144-634f700b36ef', null, array['Amboseli elephants','Kilimanjaro views','Masai Mara','Great value'], 'Easy', 2, 8, 'Nairobi', 'Nairobi', 'published', false, false, 'Kenya Classic Value Safari', 'A 5-day value safari through Amboseli and the Masai Mara.', '00000000-0000-4000-8000-000000000001', '00000000-0000-4000-8000-000000000001'),
  -- Rwanda (103)
  ('00000000-0000-4000-8000-000000000316', 'Rwanda Gorilla Trek in Style', 'rwanda-gorilla-trek-in-style', 'Five luxurious days with mountain gorillas in Volcanoes National Park.', 'Trek to a habituated gorilla family from a luxury highland lodge, with golden-monkey tracking and Kigali''s moving history.', '00000000-0000-4000-8000-000000000103', '00000000-0000-4000-8000-000000000204', 'gorilla', array['couple'], 5, 4, 'luxury', 5200, 'USD', 'https://images.unsplash.com/photo-1547471080-7cc2caa01a7e', 'https://images.unsplash.com/photo-1521651201144-634f700b36ef', array['Mountain gorillas','Golden monkeys','Luxury lodge','Kigali history'], 'Challenging', 2, 6, 'Kigali', 'Kigali', 'published', true, true, 'Rwanda Gorilla Trek in Style', 'A 5-day luxury gorilla trek in Rwanda''s Volcanoes National Park.', '00000000-0000-4000-8000-000000000001', '00000000-0000-4000-8000-000000000001'),
  ('00000000-0000-4000-8000-000000000317', 'Rwanda Gorillas & Lake Kivu', 'rwanda-gorillas-lake-kivu', 'A relaxed four-day gorilla trek with lakeside downtime.', 'Pair a gorilla trek with restful days on Lake Kivu — a gentle, scenic introduction to Rwanda.', '00000000-0000-4000-8000-000000000103', '00000000-0000-4000-8000-000000000204', 'gorilla', array['couple','solo'], 4, 3, 'mid_range', 3800, 'USD', 'https://images.unsplash.com/photo-1523805009345-7448845a9e53', null, array['Gorilla trek','Lake Kivu','Coffee experience','Scenic drives'], 'Moderate', 2, 6, 'Kigali', 'Kigali', 'published', false, false, 'Rwanda Gorillas & Lake Kivu', 'A 4-day Rwanda gorilla trek with Lake Kivu downtime.', '00000000-0000-4000-8000-000000000001', '00000000-0000-4000-8000-000000000001'),
  ('00000000-0000-4000-8000-000000000318', 'Rwanda Primates & Nyungwe', 'rwanda-primates-nyungwe', 'Six days of gorillas, chimps and canopy walks.', 'Gorillas in the Volcanoes plus chimpanzees and a canopy walk in Nyungwe Forest — for keen primate lovers.', '00000000-0000-4000-8000-000000000103', '00000000-0000-4000-8000-000000000204', 'gorilla', array['group'], 6, 5, 'luxury', 4900, 'USD', 'https://images.unsplash.com/photo-1534177616072-ef7dc120449d', null, array['Gorillas','Chimpanzees','Nyungwe canopy walk','Rainforest'], 'Challenging', 2, 6, 'Kigali', 'Kigali', 'published', false, true, 'Rwanda Primates & Nyungwe', 'A 6-day Rwanda primates trip with gorillas, chimps and Nyungwe.', '00000000-0000-4000-8000-000000000001', '00000000-0000-4000-8000-000000000001'),
  -- Uganda (104)
  ('00000000-0000-4000-8000-000000000319', 'Uganda Gorillas, Chimps & Savanna', 'uganda-gorillas-chimps-savanna', 'Seven days combining Bwindi gorillas, Kibale chimps and big game.', 'Uganda''s greatest hits in one trip: gorilla trekking in Bwindi, chimps in Kibale and savanna game viewing in Queen Elizabeth NP.', '00000000-0000-4000-8000-000000000104', '00000000-0000-4000-8000-000000000204', 'gorilla', array['couple','group'], 7, 6, 'mid_range', 4100, 'USD', 'https://images.unsplash.com/photo-1502784444187-359ac186c5bb', 'https://images.unsplash.com/photo-1547471080-7cc2caa01a7e', array['Bwindi gorillas','Kibale chimps','Queen Elizabeth NP','Tree-climbing lions','Boat safari'], 'Challenging', 2, 6, 'Entebbe', 'Entebbe', 'published', true, true, 'Uganda Gorillas, Chimps & Savanna', 'A 7-day Uganda trip with Bwindi gorillas, Kibale chimps and savanna safari.', '00000000-0000-4000-8000-000000000001', '00000000-0000-4000-8000-000000000001'),
  ('00000000-0000-4000-8000-000000000320', 'Uganda Budget Gorilla Trek', 'uganda-budget-gorilla-trek', 'Affordable five-day gorilla trekking in Bwindi.', 'The most affordable way to meet mountain gorillas, with comfortable lodges and a focus on Bwindi.', '00000000-0000-4000-8000-000000000104', '00000000-0000-4000-8000-000000000204', 'gorilla', array['solo','group'], 5, 4, 'budget', 2200, 'USD', 'https://images.unsplash.com/photo-1521651201144-634f700b36ef', null, array['Bwindi gorillas','Affordable permits','Community visit','Forest trek'], 'Challenging', 2, 8, 'Entebbe', 'Entebbe', 'published', false, false, 'Uganda Budget Gorilla Trek', 'A 5-day affordable gorilla trek in Bwindi, Uganda.', '00000000-0000-4000-8000-000000000001', '00000000-0000-4000-8000-000000000001'),
  ('00000000-0000-4000-8000-000000000321', 'Uganda Grand Wildlife Journey', 'uganda-grand-wildlife-journey', 'Ten days across Uganda''s forests, savannas and lakes.', 'A comprehensive Uganda journey — gorillas, chimps, big game, the Nile at Murchison Falls and scenic crater lakes.', '00000000-0000-4000-8000-000000000104', '00000000-0000-4000-8000-000000000206', 'safari', array['group','couple'], 10, 9, 'luxury', 6200, 'USD', 'https://images.unsplash.com/photo-1505765050516-f72dcac9c60e', null, array['Murchison Falls','Gorillas & chimps','Crater lakes','Nile boat safari'], 'Moderate', 2, 6, 'Entebbe', 'Entebbe', 'published', false, true, 'Uganda Grand Wildlife Journey', 'A 10-day grand Uganda wildlife journey across forests, savanna and the Nile.', '00000000-0000-4000-8000-000000000001', '00000000-0000-4000-8000-000000000001'),
  -- Zanzibar (105)
  ('00000000-0000-4000-8000-000000000322', 'Zanzibar Luxury Beach Escape', 'zanzibar-luxury-beach-escape', 'Six barefoot-luxury days on the Indian Ocean.', 'Unwind at a beachfront boutique resort with spice tours, Stone Town and dhow sunset cruises — the perfect safari finale.', '00000000-0000-4000-8000-000000000105', '00000000-0000-4000-8000-000000000205', 'beach', array['couple'], 6, 5, 'luxury', 3300, 'USD', 'https://images.unsplash.com/photo-1605731414532-6b26976cc153', 'https://images.unsplash.com/photo-1558998708-ce92a9c8da00', array['White-sand beaches','Stone Town','Spice tour','Dhow sunset cruise','Snorkelling'], 'Easy', 2, 4, 'Zanzibar', 'Zanzibar', 'published', true, true, 'Zanzibar Luxury Beach Escape', 'A 6-day luxury Zanzibar beach escape with Stone Town and spice tours.', '00000000-0000-4000-8000-000000000001', '00000000-0000-4000-8000-000000000001'),
  ('00000000-0000-4000-8000-000000000323', 'Zanzibar Honeymoon Retreat', 'zanzibar-honeymoon-retreat', 'Five romantic days for two on the islands.', 'A romance-focused island stay with private dinners, a sandbank picnic and total relaxation.', '00000000-0000-4000-8000-000000000105', '00000000-0000-4000-8000-000000000205', 'beach', array['couple'], 5, 4, 'luxury', 3000, 'USD', 'https://images.unsplash.com/photo-1564760055775-d63b17a55c44', null, array['Private dinners','Sandbank picnic','Couples spa','Sunset dhow'], 'Easy', 2, 2, 'Zanzibar', 'Zanzibar', 'published', false, false, 'Zanzibar Honeymoon Retreat', 'A 5-day romantic Zanzibar honeymoon retreat.', '00000000-0000-4000-8000-000000000001', '00000000-0000-4000-8000-000000000001'),
  ('00000000-0000-4000-8000-000000000324', 'Serengeti & Zanzibar Safari + Beach', 'serengeti-zanzibar-safari-beach', 'Seven days pairing the Serengeti with a Zanzibar finish.', 'The classic combo: big-game safari in the Serengeti followed by barefoot beach days in Zanzibar, seamlessly connected.', '00000000-0000-4000-8000-000000000105', '00000000-0000-4000-8000-000000000206', 'safari', array['couple','family'], 7, 6, 'mid_range', 3600, 'USD', 'https://images.unsplash.com/photo-1571406252241-db0280bd36cd', null, array['Serengeti safari','Zanzibar beaches','Light-aircraft hop','Safari + beach'], 'Easy', 2, 6, 'Kilimanjaro Airport', 'Zanzibar', 'published', false, true, 'Serengeti & Zanzibar Safari and Beach', 'A 7-day Serengeti safari and Zanzibar beach combination.', '00000000-0000-4000-8000-000000000001', '00000000-0000-4000-8000-000000000001')
on conflict (id) do update set
  title = excluded.title, slug = excluded.slug, short_description = excluded.short_description, full_description = excluded.full_description,
  destination_id = excluded.destination_id, category_id = excluded.category_id, experience_type = excluded.experience_type, persona_tags = excluded.persona_tags,
  duration_days = excluded.duration_days, duration_nights = excluded.duration_nights, budget_tier = excluded.budget_tier, price_from = excluded.price_from,
  currency = excluded.currency, main_image_url = excluded.main_image_url, banner_image_url = excluded.banner_image_url, highlights = excluded.highlights,
  difficulty_level = excluded.difficulty_level, group_size_min = excluded.group_size_min, group_size_max = excluded.group_size_max,
  start_location = excluded.start_location, end_location = excluded.end_location, status = excluded.status,
  is_featured = excluded.is_featured, is_popular = excluded.is_popular, meta_title = excluded.meta_title, meta_description = excluded.meta_description;

-- Make the 3 base tours richer too (budget tier + highlights + start/end so cards look full).
update tours set budget_tier = coalesce(budget_tier, 'mid_range'),
  highlights = case when coalesce(array_length(highlights, 1), 0) = 0 then array['Serengeti','Ngorongoro Crater','Big Five','Expert guide'] else highlights end,
  start_location = coalesce(start_location, 'Arusha'), end_location = coalesce(end_location, 'Arusha'), is_popular = true
where id = '00000000-0000-4000-8000-000000000301';
update tours set budget_tier = coalesce(budget_tier, 'mid_range'),
  highlights = case when coalesce(array_length(highlights, 1), 0) = 0 then array['Masai Mara','Diani Beach','Big cats','Indian Ocean'] else highlights end,
  start_location = coalesce(start_location, 'Nairobi'), end_location = coalesce(end_location, 'Diani'), is_popular = true
where id = '00000000-0000-4000-8000-000000000302';
update tours set budget_tier = coalesce(budget_tier, 'mid_range'),
  highlights = case when coalesce(array_length(highlights, 1), 0) = 0 then array['Uhuru Peak','Machame route','Glaciers','Mountain crew'] else highlights end,
  start_location = coalesce(start_location, 'Moshi'), end_location = coalesce(end_location, 'Moshi')
where id = '00000000-0000-4000-8000-000000000303';

