-- ---------- TESTIMONIALS (with ratings) ----------
insert into testimonials (id, client_name, client_country, client_image_url, rating, message, tour_id, status, is_featured, sort_order)
values
  ('00000000-0000-4000-8000-0000000e0001', 'Sarah & James Holloway', 'United Kingdom', 'https://i.pravatar.cc/120?img=12', 5, 'From the first call they listened and tailored everything to us. The Serengeti exceeded every expectation and the balloon flight was unforgettable.', '00000000-0000-4000-8000-000000000310', 'published', true, 1),
  ('00000000-0000-4000-8000-0000000e0002', 'Michael Chen', 'United States', 'https://i.pravatar.cc/120?img=33', 5, 'Our Masai Mara trip was flawless — incredible guides, perfect timing for the crossings, and zero stress. Worth every penny.', '00000000-0000-4000-8000-000000000313', 'published', true, 2),
  ('00000000-0000-4000-8000-0000000e0003', 'Amelia Brandt', 'Germany', 'https://i.pravatar.cc/120?img=45', 5, 'Trekking to the gorillas in Rwanda was the most moving hour of my life. Goldfinch handled permits and logistics perfectly.', '00000000-0000-4000-8000-000000000316', 'published', true, 3),
  ('00000000-0000-4000-8000-0000000e0004', 'The Okafor Family', 'Canada', 'https://i.pravatar.cc/120?img=15', 5, 'Travelling with three kids felt effortless. Short drives, family rooms and guides who kept everyone excited. Highly recommend.', '00000000-0000-4000-8000-000000000311', 'published', true, 4),
  ('00000000-0000-4000-8000-0000000e0005', 'Lucia Romano', 'Italy', 'https://i.pravatar.cc/120?img=20', 4, 'Beautiful Zanzibar honeymoon. The resort was stunning and the sandbank picnic was magical. A couple of transfers ran late but the team fixed it quickly.', '00000000-0000-4000-8000-000000000323', 'published', true, 5),
  ('00000000-0000-4000-8000-0000000e0006', 'David Mwangi', 'Kenya', 'https://i.pravatar.cc/120?img=50', 5, 'As an East African I am picky about safaris — these guides are the real deal. Honest advice, no upselling.', null, 'published', true, 6),
  ('00000000-0000-4000-8000-0000000e0007', 'Hannah Svensson', 'Sweden', 'https://i.pravatar.cc/120?img=24', 5, 'The Uganda combo of gorillas, chimps and savanna was the trip of a lifetime. So well routed.', '00000000-0000-4000-8000-000000000319', 'published', false, 7),
  ('00000000-0000-4000-8000-0000000e0008', 'Robert & Anne Fischer', 'Australia', 'https://i.pravatar.cc/120?img=60', 5, 'Laikipia''s private conservancies were extraordinary — rhino on foot and barely another vehicle in sight.', '00000000-0000-4000-8000-000000000314', 'published', false, 8),
  ('00000000-0000-4000-8000-0000000e0009', 'Priya Nair', 'India', 'https://i.pravatar.cc/120?img=32', 4, 'Great value camping safari. Basic but comfortable, and the wildlife was spectacular. Bring a warm jacket for the mornings!', '00000000-0000-4000-8000-000000000312', 'published', false, 9),
  ('00000000-0000-4000-8000-0000000e0010', 'Thomas Müller', 'Germany', 'https://i.pravatar.cc/120?img=11', 5, 'Serengeti then Zanzibar — the perfect mix of adventure and relaxation. The light-aircraft hop made it seamless.', '00000000-0000-4000-8000-000000000324', 'published', false, 10),
  ('00000000-0000-4000-8000-0000000e0011', 'Grace Adeyemi', 'Nigeria', 'https://i.pravatar.cc/120?img=49', 5, 'Climbed Kilimanjaro with their crew and summited on my first attempt. The preparation guidance was spot on.', '00000000-0000-4000-8000-000000000303', 'published', false, 11),
  ('00000000-0000-4000-8000-0000000e0012', 'Emily Carter', 'United States', 'https://i.pravatar.cc/120?img=47', 5, 'Responsive, knowledgeable and genuinely kind. They felt like friends planning our trip, not a faceless agency.', null, 'published', true, 12)
on conflict (id) do update set
  client_name = excluded.client_name, client_country = excluded.client_country, client_image_url = excluded.client_image_url,
  rating = excluded.rating, message = excluded.message, tour_id = excluded.tour_id, status = excluded.status,
  is_featured = excluded.is_featured, sort_order = excluded.sort_order;

