-- =====================================================================
-- RICH CONTENT PASS — full descriptions, itineraries, and MORE of
-- everything (experiences, lodges, activities, gateways, safety, styles,
-- comparisons, testimonials, bookings). All richly written.
-- =====================================================================

-- ---------- rich full descriptions + remaining tour fields ----------
update tours set seo_title = title || ' | Goldfinch Adventures', minimum_age = coalesce(minimum_age, 6) where id::text like '00000000-0000-4000-8000-0000000003%';

update tours set full_description = 'This flagship northern-circuit safari is built around the rhythm of the Serengeti. You will spend unhurried days tracking big cats across the southern and central plains, descend into the wildlife amphitheatre of the Ngorongoro Crater, and rise before dawn for a hot-air balloon flight over the herds. Nights are spent in genuinely luxurious tented camps where the canvas walls are the only thing between you and the sounds of the bush. Every drive is private, every detail anticipated, and your guide is among the most experienced in the country.', minimum_age = 8 where id = '00000000-0000-4000-8000-000000000310';
update tours set full_description = 'A safari designed entirely around travelling with children. Game drives are kept short and engaging, lodges have family rooms and pools, and our guides are specialists at turning curious kids into wide-eyed young naturalists. You will explore Tarangire''s elephant herds, the Serengeti''s big cats and the Ngorongoro Crater, with plenty of downtime built in so nobody gets overtired. A Maasai village visit brings the culture to life for the whole family.' where id = '00000000-0000-4000-8000-000000000311';
update tours set full_description = 'Proof that a classic Tanzanian safari does not have to cost a fortune. Travelling in a small group with a shared guide, you will cover the Serengeti and Ngorongoro Crater by day and sleep in well-equipped campsites under enormous starry skies. It is hands-on, sociable and authentic — the wildlife is exactly the same as on the luxury trips, and the campfire evenings are unforgettable.' where id = '00000000-0000-4000-8000-000000000312';
update tours set full_description = 'Timed to the drama of the Great Migration, this Masai Mara safari puts you in the heart of the action. From a classic tented camp inside the reserve you will witness river crossings, follow resident lion prides and watch cheetah hunt across the open plains. An optional dawn balloon flight and a visit to a Maasai community round out one of Africa''s greatest wildlife experiences.', minimum_age = 8 where id = '00000000-0000-4000-8000-000000000313';
update tours set full_description = 'The most exclusive way to see Kenya. You will stay in private conservancies in Laikipia, where night drives, walking safaris and rhino tracking are possible away from the crowds, before flying to a premium camp in the Masai Mara. Light-aircraft transfers, private guiding and some of the finest lodges in East Africa make this a truly special, seamless journey.', minimum_age = 12 where id = '00000000-0000-4000-8000-000000000314';
update tours set full_description = 'A wonderful-value introduction to Kenya''s wildlife. Begin in Amboseli, where great elephant herds move beneath the snows of Kilimanjaro, then transfer to the legendary Masai Mara for big-cat country. Comfortable lodges, honest pricing and superb game viewing make this an ideal first safari.' where id = '00000000-0000-4000-8000-000000000315';
update tours set full_description = 'A polished, luxurious gorilla adventure. From a beautiful highland lodge you will trek into the bamboo forests of Volcanoes National Park for a permitted hour with a habituated mountain gorilla family — one of the most moving wildlife encounters on earth. There is time to track golden monkeys and to reflect at Kigali''s thoughtful memorial and vibrant markets.', minimum_age = 15 where id = '00000000-0000-4000-8000-000000000316';
update tours set full_description = 'A gentler way to experience Rwanda. Pair a single gorilla trek with restful days beside Lake Kivu, where you can swim, take a boat trip and visit a local coffee washing station. The scenic drives through Rwanda''s terraced ''land of a thousand hills'' are an attraction in themselves.', minimum_age = 15 where id = '00000000-0000-4000-8000-000000000317';
update tours set full_description = 'For dedicated primate lovers. This trip combines mountain gorillas in the Volcanoes with chimpanzee tracking and a thrilling canopy walk in the ancient rainforest of Nyungwe. It is active and rewarding, with comfortable lodges and expert trackers throughout.', minimum_age = 15 where id = '00000000-0000-4000-8000-000000000318';
update tours set full_description = 'Uganda''s greatest hits in one well-routed week. Trek to mountain gorillas in the mist of Bwindi, track chimpanzees in Kibale Forest, and enjoy classic savanna game viewing and a boat safari on the Kazinga Channel in Queen Elizabeth National Park — where lions are known to climb trees. A rich, varied trip for travellers who want it all.', minimum_age = 15 where id = '00000000-0000-4000-8000-000000000319';
update tours set full_description = 'The most affordable route to a mountain-gorilla encounter. Focused on Bwindi Impenetrable Forest, this trip keeps costs down without cutting the experience short — comfortable lodges, a full trek with expert trackers, and a community visit that supports local conservation.', minimum_age = 15 where id = '00000000-0000-4000-8000-000000000320';
update tours set full_description = 'A comprehensive ten-day journey across Uganda. Stand above the thundering Nile at Murchison Falls, trek for gorillas and chimps, search the crater-lake region for wildlife, and cruise the Kazinga Channel. It is a big, satisfying loop for travellers with time to see the country properly.', minimum_age = 12 where id = '00000000-0000-4000-8000-000000000321';
update tours set full_description = 'Pure Indian Ocean indulgence. Settle into a beachfront boutique resort on Zanzibar''s finest sands, with snorkelling on the reef, a guided spice tour, a wander through historic Stone Town and a sunset dhow cruise. The ideal way to slow down after a safari — or simply a blissful beach holiday in its own right.' where id = '00000000-0000-4000-8000-000000000322';
update tours set full_description = 'Designed for two. This romantic island escape pairs a stylish beachfront stay with private candlelit dinners, a sandbank picnic for just the two of you, a couples'' spa treatment and a sunset dhow cruise. Effortless, intimate and utterly relaxing.', minimum_age = 18 where id = '00000000-0000-4000-8000-000000000323';
update tours set full_description = 'The classic East African combination. Spend the first half of your trip on a big-game safari in the Serengeti, then take a short light-aircraft hop to Zanzibar for barefoot beach days. Adventure and relaxation in perfect balance, seamlessly connected so you never think about logistics.' where id = '00000000-0000-4000-8000-000000000324';

-- ---------- itinerary days for the 5 showcase-featured tours ----------
insert into itinerary_days (tour_id, day_number, title, description, accommodation, meals, activities)
values
  ('00000000-0000-4000-8000-000000000310', 1, 'Arrive Kilimanjaro & transfer to Tarangire', 'Met on arrival and driven to your first camp on the edge of Tarangire, famous for its giant baobabs and elephant herds.', 'Luxury tented camp', 'Lunch, Dinner', 'Arrival transfer, afternoon game drive'),
  ('00000000-0000-4000-8000-000000000310', 2, 'Tarangire National Park', 'A full day exploring Tarangire''s river valleys and woodlands in search of elephant, lion and the rare fringe-eared oryx.', 'Luxury tented camp', 'Breakfast, Lunch, Dinner', 'Morning & afternoon game drives'),
  ('00000000-0000-4000-8000-000000000310', 3, 'Central Serengeti', 'Drive into the endless Serengeti plains, arriving in time for an afternoon drive in the wildlife-rich Seronera Valley.', 'Luxury tented camp', 'Breakfast, Lunch, Dinner', 'Game drive en route'),
  ('00000000-0000-4000-8000-000000000310', 4, 'Serengeti & balloon safari', 'Rise before dawn for a hot-air balloon flight over the herds, followed by a champagne bush breakfast and a full day on safari.', 'Luxury tented camp', 'Breakfast, Lunch, Dinner', 'Balloon flight, full-day game drive'),
  ('00000000-0000-4000-8000-000000000310', 5, 'Ngorongoro Crater', 'Descend into the Ngorongoro Crater, a natural amphitheatre teeming with lion, elephant, rhino and flamingo.', 'Crater-rim lodge', 'Breakfast, Lunch, Dinner', 'Full-day crater game drive'),
  ('00000000-0000-4000-8000-000000000310', 6, 'Depart Arusha', 'A leisurely morning before transferring to the airport for your onward flight.', 'n/a', 'Breakfast', 'Departure transfer'),
  ('00000000-0000-4000-8000-000000000313', 1, 'Arrive Nairobi', 'Welcome to Kenya. Transfer to your hotel and meet your guide for a trip briefing.', 'Nairobi boutique hotel', 'Dinner', 'Arrival transfer, briefing'),
  ('00000000-0000-4000-8000-000000000313', 2, 'Fly to the Masai Mara', 'A short flight to the Mara and straight into your first game drive across the legendary plains.', 'Mara tented camp', 'Breakfast, Lunch, Dinner', 'Afternoon game drive'),
  ('00000000-0000-4000-8000-000000000313', 3, 'Great Migration & river crossings', 'A full day following the herds, positioning for the dramatic Mara River crossings.', 'Mara tented camp', 'Breakfast, Lunch, Dinner', 'Full-day game drive, optional balloon'),
  ('00000000-0000-4000-8000-000000000313', 4, 'Big cats & Maasai culture', 'Track the Mara''s famous lion prides and cheetah, with an afternoon visit to a Maasai community.', 'Mara tented camp', 'Breakfast, Lunch, Dinner', 'Game drive, cultural visit'),
  ('00000000-0000-4000-8000-000000000313', 5, 'Return to Nairobi & depart', 'A final morning drive before flying back to Nairobi for your departure.', 'n/a', 'Breakfast', 'Game drive, departure transfer'),
  ('00000000-0000-4000-8000-000000000316', 1, 'Arrive Kigali', 'Arrive in Rwanda''s clean, green capital. A guided city tour includes the moving Genocide Memorial.', 'Kigali hotel', 'Dinner', 'City tour, memorial visit'),
  ('00000000-0000-4000-8000-000000000316', 2, 'Transfer to Volcanoes NP', 'A scenic drive through terraced hills to your luxury lodge at the foot of the Virunga volcanoes.', 'Highland luxury lodge', 'Breakfast, Lunch, Dinner', 'Scenic drive, lodge relaxation'),
  ('00000000-0000-4000-8000-000000000316', 3, 'Gorilla trek', 'The big day: trek into the bamboo forest for a permitted hour with a habituated mountain gorilla family.', 'Highland luxury lodge', 'Breakfast, Lunch, Dinner', 'Gorilla trek'),
  ('00000000-0000-4000-8000-000000000316', 4, 'Golden monkeys & culture', 'Track playful golden monkeys in the morning and visit a local community in the afternoon.', 'Highland luxury lodge', 'Breakfast, Lunch, Dinner', 'Golden monkey trek, cultural visit'),
  ('00000000-0000-4000-8000-000000000316', 5, 'Depart Kigali', 'Return to Kigali for last-minute shopping and your departure flight.', 'n/a', 'Breakfast', 'Departure transfer'),
  ('00000000-0000-4000-8000-000000000319', 1, 'Arrive Entebbe', 'Arrive and overnight on the shores of Lake Victoria.', 'Entebbe lodge', 'Dinner', 'Arrival transfer'),
  ('00000000-0000-4000-8000-000000000319', 2, 'Kibale Forest', 'Travel to Kibale, the primate capital of East Africa.', 'Forest lodge', 'Breakfast, Lunch, Dinner', 'Transfer, evening nature walk'),
  ('00000000-0000-4000-8000-000000000319', 3, 'Chimpanzee tracking', 'Track habituated chimpanzees through the forest, then explore the Bigodi wetland.', 'Forest lodge', 'Breakfast, Lunch, Dinner', 'Chimp trek, wetland walk'),
  ('00000000-0000-4000-8000-000000000319', 4, 'Queen Elizabeth NP', 'Game drives and a Kazinga Channel boat safari in search of tree-climbing lions, hippo and elephant.', 'Savanna lodge', 'Breakfast, Lunch, Dinner', 'Game drive, boat safari'),
  ('00000000-0000-4000-8000-000000000319', 5, 'Transfer to Bwindi', 'A scenic drive south to the edge of the ancient Bwindi Impenetrable Forest.', 'Bwindi lodge', 'Breakfast, Lunch, Dinner', 'Scenic transfer'),
  ('00000000-0000-4000-8000-000000000319', 6, 'Gorilla trek', 'Trek into Bwindi for an unforgettable hour with a mountain gorilla family.', 'Bwindi lodge', 'Breakfast, Lunch, Dinner', 'Gorilla trek'),
  ('00000000-0000-4000-8000-000000000319', 7, 'Return & depart', 'Fly or drive back to Entebbe for your departure.', 'n/a', 'Breakfast', 'Departure transfer'),
  ('00000000-0000-4000-8000-000000000322', 1, 'Arrive Zanzibar', 'Transfer to your beachfront resort and unwind with your toes in the sand.', 'Beachfront resort', 'Dinner', 'Arrival transfer'),
  ('00000000-0000-4000-8000-000000000322', 2, 'Stone Town & spices', 'A guided walk through historic Stone Town followed by a working spice-farm tour.', 'Beachfront resort', 'Breakfast', 'Stone Town tour, spice tour'),
  ('00000000-0000-4000-8000-000000000322', 3, 'Reef snorkelling', 'A boat trip to the reef for snorkelling in clear turquoise water.', 'Beachfront resort', 'Breakfast, Lunch', 'Snorkelling excursion'),
  ('00000000-0000-4000-8000-000000000322', 4, 'Beach & dhow cruise', 'A relaxed beach day rounded off with a traditional sunset dhow cruise.', 'Beachfront resort', 'Breakfast', 'Beach time, sunset cruise'),
  ('00000000-0000-4000-8000-000000000322', 5, 'Depart', 'A final morning on the beach before your departure transfer.', 'n/a', 'Breakfast', 'Departure transfer')
on conflict (tour_id, day_number) do update set
  title = excluded.title, description = excluded.description, accommodation = excluded.accommodation, meals = excluded.meals, activities = excluded.activities;

-- ---------- MORE experiences (categories) — richly enriched ----------
insert into tour_categories (id, name, slug, description, who_its_for, fitness, highlights, image_url, status, sort_order, meta_description)
values
  ('00000000-0000-4000-8000-000000000207', 'Photography Safari', 'photography-safari', 'Itineraries built around light, wildlife density and vehicle access — for travellers who care about the shot.', 'Keen photographers, from enthusiasts with a first zoom lens to seasoned pros chasing portfolio images.', 'Easy — long, patient hours in the vehicle rather than walking.', array['Golden-hour positioning','Time at sightings, not rushing','Bean bags & space to shoot','Migration & predator timing'], 'https://images.unsplash.com/photo-1534177616072-ef7dc120449d', 'published', 7, 'Plan a wildlife photography safari built around the best light and access.'),
  ('00000000-0000-4000-8000-000000000208', 'Walking Safari', 'walking-safari', 'Experience the bush on foot with armed, expert guides — the oldest and most intimate way to safari.', 'Active travellers who want to feel the wilderness, not just watch it from a vehicle.', 'Moderate — gentle walks of two to three hours on uneven ground.', array['Tracking on foot','Reading signs & smells','Small groups','Remote wilderness areas'], 'https://images.unsplash.com/photo-1549366021-9f761d450615', 'published', 8, 'Plan a guided walking safari in East Africa''s wild areas.'),
  ('00000000-0000-4000-8000-000000000209', 'Cultural Journeys', 'cultural-journeys', 'Meet the people of East Africa — Maasai, Hadzabe, Swahili and more — through respectful, genuine encounters.', 'Curious travellers who want depth and human connection alongside the wildlife.', 'Easy — village visits, markets and short walks.', array['Maasai & Hadzabe communities','Local markets & crafts','Swahili coast heritage','Community-led tourism'], 'https://images.unsplash.com/photo-1523805009345-7448845a9e53', 'published', 9, 'Plan a culturally rich East Africa journey with respectful community encounters.'),
  ('00000000-0000-4000-8000-000000000210', 'Honeymoon & Romance', 'honeymoon-romance', 'Private, intimate trips for two — safari by day, romance by night, with thoughtful special-occasion touches.', 'Honeymooners, anniversaries and anyone celebrating love.', 'Easy — relaxed and romantic throughout.', array['Private, intimate camps','Safari + Zanzibar combinations','Candlelit & sandbank dinners','Effortless, handled planning'], 'https://images.unsplash.com/photo-1564760055775-d63b17a55c44', 'published', 10, 'Plan a romantic honeymoon safari and beach escape in East Africa.'),
  ('00000000-0000-4000-8000-000000000211', 'Family Safari', 'family-safari', 'Safaris paced for children — shorter drives, safe family lodges and guides who turn kids into explorers.', 'Families with children of all ages, from toddlers to teens.', 'Easy — flexible pace with plenty of downtime.', array['Kid-friendly pace & rooms','Big Five without long drives','Educational, hands-on moments','Family rooms & flexible meals'], 'https://images.unsplash.com/photo-1535941339077-2dd1c7963098', 'published', 11, 'Plan a family safari in East Africa, paced and priced for children.'),
  ('00000000-0000-4000-8000-000000000212', 'Migration Safari', 'migration-safari', 'Follow the Great Migration — calving, river crossings and predator drama — timed to where the herds are.', 'Wildlife lovers who want the greatest show on earth at exactly the right moment.', 'Easy — vehicle-based game viewing.', array['River crossings (Jul–Oct)','Calving season (Jan–Mar)','Predator action','Serengeti & Masai Mara'], 'https://images.unsplash.com/photo-1516426122078-c23e76319801', 'published', 12, 'Plan a Great Migration safari timed to the herds in the Serengeti and Masai Mara.')
on conflict (id) do update set
  name = excluded.name, slug = excluded.slug, description = excluded.description, who_its_for = excluded.who_its_for,
  fitness = excluded.fitness, highlights = excluded.highlights, image_url = excluded.image_url, status = excluded.status,
  sort_order = excluded.sort_order, meta_description = excluded.meta_description;

-- ---------- MORE lodges (richly described) ----------
insert into lodges (id, name, slug, destination_id, accommodation_level, lodge_type, description, why_we_recommend, hero_image_url, image_url, price_per_night_from, currency, best_for, romantic_rating, family_rating, website_url, status, is_featured, meta_title, meta_description, created_by, updated_by)
values
  ('00000000-0000-4000-8000-000000000505', 'Tarangire Treetops', 'tarangire-treetops', '00000000-0000-4000-8000-000000000101', 'luxury', 'treehouse', 'Elevated treehouse suites built around ancient baobab and marula trees, overlooking a waterhole alive with elephant.', 'A genuinely different stay — falling asleep in a treehouse above the herds is pure magic, and it pairs beautifully with the northern circuit.', 'https://images.unsplash.com/photo-1535941339077-2dd1c7963098', 'https://images.unsplash.com/photo-1535941339077-2dd1c7963098', 720, 'USD', array['Couples','Something different','Elephants'], 9.2, 7.0, 'https://example.com', 'published', true, 'Tarangire Treetops', 'Luxury baobab treehouse suites overlooking a Tarangire waterhole.', '00000000-0000-4000-8000-000000000001', '00000000-0000-4000-8000-000000000001'),
  ('00000000-0000-4000-8000-000000000506', 'Mara Plains Camp', 'mara-plains-camp', '00000000-0000-4000-8000-000000000102', 'ultra_luxury', 'tented_camp', 'A small, intimate camp in a private conservancy bordering the Masai Mara, with just a handful of spacious tented suites.', 'Conservancy access means night drives and walking — and almost no other vehicles at sightings. Our top pick for an exclusive Mara stay.', 'https://images.unsplash.com/photo-1516026672322-bc52d61a55d5', 'https://images.unsplash.com/photo-1516026672322-bc52d61a55d5', 1650, 'USD', array['Honeymoon','Exclusivity','Big cats'], 9.7, 6.0, 'https://example.com', 'published', true, 'Mara Plains Camp', 'An ultra-luxury conservancy camp bordering the Masai Mara.', '00000000-0000-4000-8000-000000000001', '00000000-0000-4000-8000-000000000001'),
  ('00000000-0000-4000-8000-000000000507', 'Bisate Lodge', 'bisate-lodge', '00000000-0000-4000-8000-000000000103', 'ultra_luxury', 'lodge', 'Striking dome-shaped villas set in a reforested volcanic amphitheatre near Volcanoes National Park.', 'Conservation-led luxury at its finest — the architecture, the views and the gorilla access are all world-class.', 'https://images.unsplash.com/photo-1547471080-7cc2caa01a7e', 'https://images.unsplash.com/photo-1547471080-7cc2caa01a7e', 1850, 'USD', array['Honeymoon','Gorilla trekking','Conservation'], 9.6, 6.5, 'https://example.com', 'published', false, 'Bisate Lodge', 'Conservation-led luxury villas near Rwanda''s Volcanoes National Park.', '00000000-0000-4000-8000-000000000001', '00000000-0000-4000-8000-000000000001'),
  ('00000000-0000-4000-8000-000000000508', 'Bwindi Forest Lodge', 'bwindi-forest-lodge', '00000000-0000-4000-8000-000000000104', 'luxury', 'lodge', 'A cosy eco-lodge on the edge of the Bwindi Impenetrable Forest, with log fires and forest-facing cottages.', 'Minutes from the trailhead and wonderfully warming after a muddy gorilla trek — the perfect Bwindi base.', 'https://images.unsplash.com/photo-1502784444187-359ac186c5bb', 'https://images.unsplash.com/photo-1502784444187-359ac186c5bb', 540, 'USD', array['Gorilla trekking','Couples','Eco'], 8.4, 7.0, 'https://example.com', 'published', false, 'Bwindi Forest Lodge', 'A luxury eco-lodge on the edge of Bwindi Impenetrable Forest.', '00000000-0000-4000-8000-000000000001', '00000000-0000-4000-8000-000000000001'),
  ('00000000-0000-4000-8000-000000000509', 'Matemwe Beach Villa', 'matemwe-beach-villa', '00000000-0000-4000-8000-000000000105', 'luxury', 'hotel', 'Whitewashed beachfront villas on Zanzibar''s quiet northeast coast, looking across to Mnemba Atoll.', 'Barefoot luxury with superb snorkelling on the doorstep — our favourite for a safari-and-beach finale.', 'https://images.unsplash.com/photo-1605731414532-6b26976cc153', 'https://images.unsplash.com/photo-1605731414532-6b26976cc153', 480, 'USD', array['Honeymoon','Beach','Snorkelling'], 9.3, 7.5, 'https://example.com', 'published', true, 'Matemwe Beach Villa', 'Beachfront luxury villas on Zanzibar facing Mnemba Atoll.', '00000000-0000-4000-8000-000000000001', '00000000-0000-4000-8000-000000000001'),
  ('00000000-0000-4000-8000-000000000510', 'Serengeti Mobile Camp', 'serengeti-mobile-camp', '00000000-0000-4000-8000-000000000101', 'mid_range', 'mobile_camp', 'A classic mobile camp that moves seasonally to stay close to the Great Migration, with comfortable en-suite tents.', 'Following the herds means front-row migration access at a sensible price — authentic, low-impact and brilliantly located.', 'https://images.unsplash.com/photo-1504432842672-1a79f78e4084', 'https://images.unsplash.com/photo-1504432842672-1a79f78e4084', 390, 'USD', array['Migration','Value','First safari'], 7.5, 8.0, 'https://example.com', 'published', false, 'Serengeti Mobile Camp', 'A migration-following mobile camp in the Serengeti.', '00000000-0000-4000-8000-000000000001', '00000000-0000-4000-8000-000000000001')
on conflict (id) do update set
  name = excluded.name, slug = excluded.slug, destination_id = excluded.destination_id, accommodation_level = excluded.accommodation_level,
  lodge_type = excluded.lodge_type, description = excluded.description, why_we_recommend = excluded.why_we_recommend,
  hero_image_url = excluded.hero_image_url, image_url = excluded.image_url, price_per_night_from = excluded.price_per_night_from,
