  website_url = excluded.website_url, status = excluded.status, is_featured = excluded.is_featured, meta_title = excluded.meta_title, meta_description = excluded.meta_description;

-- ---------- MORE activities (richly described) ----------
insert into activities (id, name, slug, destination_id, location_label, category, difficulty, description, why_we_recommend, highlights, hero_image_url, image_url, duration_label, price_from, currency, price_unit, badge, best_season, status, is_featured, meta_title, meta_description, created_by, updated_by)
values
  ('00000000-0000-4000-8000-000000000606', 'Walking Safari with a Ranger', 'walking-safari-with-a-ranger', '00000000-0000-4000-8000-000000000102', 'Laikipia', 'adventure', 'moderate', 'Step out of the vehicle and into the bush on a guided walk, learning to read tracks, signs and the smaller wonders most safaris miss.', 'There is nothing like being on foot in big-game country with an expert — it changes how you see the wilderness forever.', array['Tracking on foot','Bush craft & signs','Small groups','Armed expert guide'], 'https://images.unsplash.com/photo-1549366021-9f761d450615', 'https://images.unsplash.com/photo-1549366021-9f761d450615', 'Half day', 120, 'USD', 'Per person', null, array['June','July','August','September','October'], 'published', true, 'Walking Safari with a Ranger', 'A guided bush walk in Laikipia with an armed expert ranger.', '00000000-0000-4000-8000-000000000001', '00000000-0000-4000-8000-000000000001'),
  ('00000000-0000-4000-8000-000000000607', 'Maasai Village Visit', 'maasai-village-visit', '00000000-0000-4000-8000-000000000101', 'Ngorongoro Highlands', 'cultural', 'easy', 'Spend time with a Maasai community, learning about their traditions, livestock and daily life through a respectful, community-led visit.', 'When done right — and ours are — a village visit is genuine and two-way, not a performance. A meaningful counterpoint to the wildlife.', array['Community-led','Traditions & dance','Crafts & beadwork','Support local livelihoods'], 'https://images.unsplash.com/photo-1523805009345-7448845a9e53', 'https://images.unsplash.com/photo-1523805009345-7448845a9e53', '2-3 hours', 35, 'USD', 'Per person', null, array['June','July','August','September','October','December','January','February'], 'published', false, 'Maasai Village Visit', 'A respectful, community-led Maasai cultural visit.', '00000000-0000-4000-8000-000000000001', '00000000-0000-4000-8000-000000000001'),
  ('00000000-0000-4000-8000-000000000608', 'Chimpanzee Tracking in Kibale', 'chimpanzee-tracking-kibale', '00000000-0000-4000-8000-000000000104', 'Kibale Forest', 'trekking', 'moderate', 'Track habituated chimpanzees through Kibale Forest, listening for their calls before catching up with a family feeding and grooming.', 'Kibale has the highest primate density in East Africa — the chimps are active and the forest itself is magical.', array['Habituated chimps','13 primate species','Forest walk','Expert trackers'], 'https://images.unsplash.com/photo-1535941339077-2dd1c7963098', 'https://images.unsplash.com/photo-1535941339077-2dd1c7963098', 'Half day', 250, 'USD', 'Per person (permit incl.)', 'Limited permits', array['June','July','August','September','December','January','February'], 'published', true, 'Chimpanzee Tracking in Kibale', 'Track habituated chimpanzees in Uganda''s Kibale Forest.', '00000000-0000-4000-8000-000000000001', '00000000-0000-4000-8000-000000000001'),
  ('00000000-0000-4000-8000-000000000609', 'Kazinga Channel Boat Safari', 'kazinga-channel-boat-safari', '00000000-0000-4000-8000-000000000104', 'Queen Elizabeth NP', 'water', 'easy', 'A relaxed boat cruise along the Kazinga Channel, lined with hippo, buffalo, elephant and a spectacular array of waterbirds.', 'A wonderfully different perspective on the wildlife — and a restful afternoon between game drives.', array['Hippo & elephant','Waterbirds','Relaxed cruise','Great photography'], 'https://images.unsplash.com/photo-1549366021-9f761d450615', 'https://images.unsplash.com/photo-1549366021-9f761d450615', 'Approx. 2 hours', 40, 'USD', 'Per person', null, array['June','July','August','September','December','January','February'], 'published', false, 'Kazinga Channel Boat Safari', 'A boat safari along Uganda''s wildlife-rich Kazinga Channel.', '00000000-0000-4000-8000-000000000001', '00000000-0000-4000-8000-000000000001'),
  ('00000000-0000-4000-8000-000000000610', 'Mnemba Atoll Snorkelling', 'mnemba-atoll-snorkelling', '00000000-0000-4000-8000-000000000105', 'Mnemba Atoll, Zanzibar', 'water', 'easy', 'Snorkel the protected reef around Mnemba Atoll, home to turtles, dolphins and a kaleidoscope of reef fish in warm, clear water.', 'Zanzibar''s best snorkelling — calm, vivid and easy for all abilities, often with turtles and dolphins.', array['Coral reef','Turtles & dolphins','Warm clear water','All abilities'], 'https://images.unsplash.com/photo-1564760055775-d63b17a55c44', 'https://images.unsplash.com/photo-1564760055775-d63b17a55c44', 'Half day', 75, 'USD', 'Per person', 'Popular', array['June','July','August','September','October','December','January','February','March'], 'published', true, 'Mnemba Atoll Snorkelling', 'Snorkel the protected reef around Zanzibar''s Mnemba Atoll.', '00000000-0000-4000-8000-000000000001', '00000000-0000-4000-8000-000000000001'),
  ('00000000-0000-4000-8000-000000000611', 'Lake Nakuru Flamingos & Rhino', 'lake-nakuru-flamingos-rhino', '00000000-0000-4000-8000-000000000102', 'Lake Nakuru NP', 'wildlife', 'easy', 'A game drive around alkaline Lake Nakuru, famous for its flamingos and as one of Kenya''s best rhino sanctuaries.', 'A compact park that reliably delivers rhino, flamingo and tree-climbing lions — superb value on a Kenya loop.', array['Black & white rhino','Flamingo flocks','Tree-climbing lions','Compact & rewarding'], 'https://images.unsplash.com/photo-1521651201144-634f700b36ef', 'https://images.unsplash.com/photo-1521651201144-634f700b36ef', 'Full day', 160, 'USD', 'Per person', null, array['January','February','June','July','August','September','October'], 'published', false, 'Lake Nakuru Flamingos & Rhino', 'A game drive at Lake Nakuru for flamingos and rhino.', '00000000-0000-4000-8000-000000000001', '00000000-0000-4000-8000-000000000001'),
  ('00000000-0000-4000-8000-000000000612', 'Coffee Experience, Lake Kivu', 'coffee-experience-lake-kivu', '00000000-0000-4000-8000-000000000103', 'Lake Kivu, Rwanda', 'cultural', 'easy', 'Visit a lakeside cooperative to see how Rwanda''s celebrated coffee is grown, washed and roasted — then taste the result.', 'A relaxed, delicious window into rural Rwandan life and a perfect pairing with gorilla trekking.', array['Bean to cup','Cooperative visit','Tasting','Lake Kivu views'], 'https://images.unsplash.com/photo-1523805009345-7448845a9e53', 'https://images.unsplash.com/photo-1523805009345-7448845a9e53', 'Half day', 45, 'USD', 'Per person', null, array['June','July','August','September','December','January','February'], 'published', false, 'Coffee Experience, Lake Kivu', 'A Rwandan coffee cooperative tour and tasting on Lake Kivu.', '00000000-0000-4000-8000-000000000001', '00000000-0000-4000-8000-000000000001'),
  ('00000000-0000-4000-8000-000000000613', 'Sundowner Bush Dinner', 'sundowner-bush-dinner', '00000000-0000-4000-8000-000000000101', 'Serengeti', 'relaxation', 'easy', 'Toast the day with a sundowner on the plains, followed by a candlelit dinner under the stars far from camp.', 'The most romantic, atmospheric way to end a safari day — a highlight guests talk about for years.', array['Sundowner drinks','Candlelit dinner','Stargazing','Far from camp'], 'https://images.unsplash.com/photo-1505765050516-f72dcac9c60e', 'https://images.unsplash.com/photo-1505765050516-f72dcac9c60e', 'Evening', 90, 'USD', 'Per person', null, array['June','July','August','September','October','December','January','February'], 'published', false, 'Sundowner Bush Dinner', 'A romantic sundowner and candlelit bush dinner in the Serengeti.', '00000000-0000-4000-8000-000000000001', '00000000-0000-4000-8000-000000000001')
on conflict (id) do update set
  name = excluded.name, slug = excluded.slug, destination_id = excluded.destination_id, location_label = excluded.location_label,
  category = excluded.category, difficulty = excluded.difficulty, description = excluded.description, why_we_recommend = excluded.why_we_recommend,
  highlights = excluded.highlights, hero_image_url = excluded.hero_image_url, image_url = excluded.image_url, duration_label = excluded.duration_label,
  price_from = excluded.price_from, currency = excluded.currency, price_unit = excluded.price_unit, badge = excluded.badge,
  best_season = excluded.best_season, status = excluded.status, is_featured = excluded.is_featured, meta_title = excluded.meta_title, meta_description = excluded.meta_description;

-- ---------- MORE trip points (gateways) ----------
insert into trip_points (id, name, slug, destination_id, role, gateway_type, airport_code, description, transfer_info, hero_image_url, image_url, status, is_featured, sort_order, meta_title, meta_description, created_by, updated_by)
values
  ('00000000-0000-4000-8000-000000000705', 'Entebbe International Airport', 'entebbe-international-airport', '00000000-0000-4000-8000-000000000104', 'both', 'airport', 'EBB', 'Uganda''s main international gateway, on the shores of Lake Victoria near Kampala.', 'All Uganda trips start and end here. We overnight in Entebbe before driving or flying to the parks, and arrange every transfer privately.', 'https://images.unsplash.com/photo-1502784444187-359ac186c5bb', 'https://images.unsplash.com/photo-1502784444187-359ac186c5bb', 'published', true, 5, 'Entebbe International Airport (EBB)', 'EBB is Uganda''s gateway for gorilla and savanna safaris.', '00000000-0000-4000-8000-000000000001', '00000000-0000-4000-8000-000000000001'),
  ('00000000-0000-4000-8000-000000000706', 'Abeid Amani Karume Airport', 'zanzibar-airport', '00000000-0000-4000-8000-000000000105', 'both', 'airport', 'ZNZ', 'Zanzibar''s island airport, a short hop from Dar es Salaam, Arusha and Nairobi.', 'Beach stays and safari-and-beach combos start or end here. Resort transfers take 20–75 minutes depending on the coast.', 'https://images.unsplash.com/photo-1605731414532-6b26976cc153', 'https://images.unsplash.com/photo-1605731414532-6b26976cc153', 'published', false, 6, 'Zanzibar Airport (ZNZ)', 'ZNZ is the gateway to Zanzibar''s beaches and Stone Town.', '00000000-0000-4000-8000-000000000001', '00000000-0000-4000-8000-000000000001'),
  ('00000000-0000-4000-8000-000000000707', 'Moshi', 'moshi', '00000000-0000-4000-8000-000000000101', 'start', 'city', null, 'The friendly town at the foot of Kilimanjaro and the usual base for climbs.', 'Kilimanjaro climbs begin and end in Moshi, about 45 minutes from JRO. We include a pre-climb briefing and gear check here.', 'https://images.unsplash.com/photo-1589553416260-f586c8f1514f', 'https://images.unsplash.com/photo-1589553416260-f586c8f1514f', 'published', false, 7, 'Moshi — base for Kilimanjaro', 'Moshi is the base town for Kilimanjaro climbs.', '00000000-0000-4000-8000-000000000001', '00000000-0000-4000-8000-000000000001'),
  ('00000000-0000-4000-8000-000000000708', 'Wilson Airport', 'wilson-airport', '00000000-0000-4000-8000-000000000102', 'start', 'airport', 'WIL', 'Nairobi''s domestic airport and the hub for light-aircraft safari flights.', 'Most Masai Mara and conservancy trips connect through Wilson by light aircraft — a quick, scenic 45-minute hop to the reserve.', 'https://images.unsplash.com/photo-1516026672322-bc52d61a55d5', 'https://images.unsplash.com/photo-1516026672322-bc52d61a55d5', 'published', false, 8, 'Wilson Airport (WIL)', 'Wilson is Nairobi''s hub for light-aircraft safari flights.', '00000000-0000-4000-8000-000000000001', '00000000-0000-4000-8000-000000000001')
on conflict (id) do update set
  name = excluded.name, slug = excluded.slug, destination_id = excluded.destination_id, role = excluded.role, gateway_type = excluded.gateway_type,
  airport_code = excluded.airport_code, description = excluded.description, transfer_info = excluded.transfer_info,
  hero_image_url = excluded.hero_image_url, image_url = excluded.image_url, status = excluded.status, is_featured = excluded.is_featured,
