-- ---------- MORE safety topics ----------
insert into safety_topics (id, title, slug, category, icon, summary, content, status, is_featured, sort_order, meta_title, meta_description)
values
  ('00000000-0000-4000-8000-000000000807', 'Malaria & mosquito prevention', 'malaria-mosquito-prevention', 'health', 'HeartPulse', 'Simple precautions and the right medication make malaria a very manageable risk.', 'Most safari areas carry a malaria risk, so we recommend antimalarial medication (discuss options with your doctor or travel clinic), repellent with DEET, long sleeves at dawn and dusk, and the insecticide-treated nets provided at camps. Risk is lower at altitude and on the coast, but precautions are always sensible.', 'published', false, 7, 'Malaria & mosquito prevention on safari', 'How to prevent malaria and mosquito bites on an East Africa safari.'),
  ('00000000-0000-4000-8000-000000000808', 'Altitude on Kilimanjaro', 'altitude-on-kilimanjaro', 'health', 'Mountain', 'Smart acclimatisation and a longer route dramatically improve your summit chances and safety.', 'Altitude is the single biggest factor on Kilimanjaro. We favour longer routes that allow proper acclimatisation, walk ''pole pole'' (slowly), keep you well hydrated, and our guides carry oximeters and emergency oxygen and check you twice daily. Anyone showing serious symptoms is descended immediately — your safety always comes first.', 'published', false, 8, 'Altitude safety on Kilimanjaro', 'How we manage altitude safety on Kilimanjaro climbs.'),
  ('00000000-0000-4000-8000-000000000809', 'Food & water on safari', 'food-and-water-on-safari', 'practical', 'Utensils', 'Eat well and stay hydrated with a few simple habits.', 'Camps and lodges serve excellent, freshly prepared food and safe filtered or bottled water. Stick to bottled or treated water (including for brushing teeth), enjoy the cooked meals and peeled fruit, and carry a reusable bottle — most camps refill it for you to cut down on plastic.', 'published', false, 9, 'Food & water safety on safari', 'Eating and drinking safely on an East Africa safari.'),
  ('00000000-0000-4000-8000-000000000810', 'Solo & women travellers', 'solo-and-women-travellers', 'general', 'ShieldCheck', 'East Africa is a rewarding, welcoming destination for solo and women travellers.', 'Many of our guests travel solo, including women travelling alone, and feel very safe doing so. You are accompanied by a trusted guide throughout, lodges are secure, and we are reachable around the clock. We are happy to advise on dress, etiquette and any specific concerns before you travel.', 'published', false, 10, 'Solo & women travellers in East Africa', 'Honest safety guidance for solo and women travellers in East Africa.')
on conflict (id) do update set
  title = excluded.title, slug = excluded.slug, category = excluded.category, icon = excluded.icon, summary = excluded.summary,
  content = excluded.content, status = excluded.status, is_featured = excluded.is_featured, sort_order = excluded.sort_order,
  meta_title = excluded.meta_title, meta_description = excluded.meta_description;

-- ---------- MORE travel styles ----------
insert into travel_styles (id, name, slug, emotional_promise, description, desires, concerns, persona, status, is_featured, sort_order, meta_description, created_by, updated_by)
values
  ('00000000-0000-4000-8000-000000000907', 'Adventure & Active', 'adventure-active', 'Earn the view, feel the wild', 'For travellers who want to do, not just watch — Kilimanjaro climbs, walking safaris, forest treks and active days from dawn to dusk.', array['Walking & trekking safaris','Kilimanjaro & forest hikes','Active, full days','Remote wilderness'], array['Am I fit enough?','How tough is the trek?','Right route for me'], 'solo', 'published', false, 7, 'Plan an active, adventurous East Africa trip — treks, climbs and walking safaris.', '00000000-0000-4000-8000-000000000001', '00000000-0000-4000-8000-000000000001'),
  ('00000000-0000-4000-8000-000000000908', 'Conservation & Wildlife', 'conservation-wildlife', 'Travel that gives back', 'Stay in conservancies and community lodges where your trip directly funds wildlife protection and local livelihoods.', array['Private conservancies','Rhino & predator conservation','Community-owned lodges','Low-impact travel'], array['Is it genuinely sustainable?','Where does my money go?','Ethical wildlife encounters'], null, 'published', false, 8, 'Plan a conservation-focused safari that funds wildlife and communities.', '00000000-0000-4000-8000-000000000001', '00000000-0000-4000-8000-000000000001'),
  ('00000000-0000-4000-8000-000000000909', 'Multi-generational', 'multi-generational', 'One trip the whole family remembers', 'Bring grandparents, parents and kids together with a pace and lodges that suit every generation — shared adventure, private space.', array['Rooms & pace for all ages','Connecting family suites','Flexible activities','One coordinated plan'], array['Mixed mobility & energy','Keeping everyone happy','Rooming & budgets'], 'family', 'published', false, 9, 'Plan a multi-generational family safari that works for every age.', '00000000-0000-4000-8000-000000000001', '00000000-0000-4000-8000-000000000001')
on conflict (id) do update set
  name = excluded.name, slug = excluded.slug, emotional_promise = excluded.emotional_promise, description = excluded.description,
  desires = excluded.desires, concerns = excluded.concerns, persona = excluded.persona, status = excluded.status,
  is_featured = excluded.is_featured, sort_order = excluded.sort_order, meta_description = excluded.meta_description;

-- ---------- MORE comparisons ----------
insert into comparisons (id, title, slug, eyebrow, intro, a_name, b_name, dimensions, verdict, cta_label, cta_href, faqs, status, is_featured, sort_order, created_by, updated_by)
values
  ('00000000-0000-4000-8000-000000000a04', 'Dry Season vs Green Season', 'dry-season-vs-green-season', 'When to travel', 'East Africa is rewarding year-round, but the experience changes a lot by season. Here is an honest look at the trade-offs so you can pick the right time for you.', 'Dry season (Jun–Oct)', 'Green season (Nov–May)',
   '[{"label":"Wildlife viewing","a":"Animals gather at water; sparse vegetation makes spotting easy.","b":"Lush scenery; wildlife more dispersed but still excellent."},{"label":"Crowds & price","a":"Peak season — busier and pricier.","b":"Quieter parks and better value, especially Apr–May."},{"label":"The migration","a":"River crossings in the Mara/northern Serengeti (Jul–Oct).","b":"Calving in the southern Serengeti (Jan–Mar) — predator drama."},{"label":"Weather","a":"Dry, sunny, cooler nights.","b":"Warm with short afternoon showers; vivid green light for photos."}]'::jsonb,
   'For first-timers and the river crossings, the dry season is the safe choice. For value, fewer vehicles, dramatic skies and the calving season, the green season is wonderful — and often our personal favourite. We will match the timing to what matters most to you.', 'Plan around the best season', '/plan-my-trip', '[]'::jsonb, 'published', false, 4, '00000000-0000-4000-8000-000000000001', '00000000-0000-4000-8000-000000000001'),
  ('00000000-0000-4000-8000-000000000a05', 'Lodge vs Tented Camp', 'lodge-vs-tented-camp', 'Where to stay', 'Two very different ways to sleep on safari, both wonderful. Here is how a solid lodge compares to a classic tented camp.', 'Lodge', 'Tented camp',
   '[{"label":"Feel","a":"Solid walls, often larger, with pools and amenities.","b":"Canvas under the stars — closer to the sounds of the bush."},{"label":"Comfort","a":"Air-conditioning, family rooms, very weatherproof.","b":"En-suite and comfortable, but more in tune with nature."},{"label":"Location","a":"Often on park edges or escarpments with big views.","b":"Frequently deeper in the wild, including mobile migration camps."},{"label":"Best for","a":"Families, first-timers and those who want amenities.","b":"Romantics and purists who want the authentic safari feel."}]'::jsonb,
   'Families and first-timers often prefer the reassurance and amenities of a lodge; couples and safari purists tend to love the romance of a tented camp. Many of our trips mix both. Tell us your priorities and we will build the right blend.', 'Plan your perfect stay', '/plan-my-trip', '[]'::jsonb, 'published', false, 5, '00000000-0000-4000-8000-000000000001', '00000000-0000-4000-8000-000000000001')
on conflict (id) do update set
  title = excluded.title, slug = excluded.slug, eyebrow = excluded.eyebrow, intro = excluded.intro, a_name = excluded.a_name, b_name = excluded.b_name,
  dimensions = excluded.dimensions, verdict = excluded.verdict, cta_label = excluded.cta_label, cta_href = excluded.cta_href, faqs = excluded.faqs,
  status = excluded.status, is_featured = excluded.is_featured, sort_order = excluded.sort_order;

-- ---------- MORE testimonials ----------
insert into testimonials (id, client_name, client_country, client_image_url, rating, message, tour_id, status, is_featured, sort_order)
values
  ('00000000-0000-4000-8000-0000000e0013', 'Jonas & Lena Weber', 'Switzerland', 'https://i.pravatar.cc/120?img=51', 5, 'The treehouse at Tarangire and the balloon over the Serengeti were dreamlike. Faultless planning from start to finish.', '00000000-0000-4000-8000-000000000310', 'published', false, 13),
  ('00000000-0000-4000-8000-0000000e0014', 'Aisha Abdullahi', 'United Arab Emirates', 'https://i.pravatar.cc/120?img=44', 5, 'Our family of six was looked after beautifully. The guides were endlessly patient with the children. We are already planning the next one.', '00000000-0000-4000-8000-000000000311', 'published', false, 14),
  ('00000000-0000-4000-8000-0000000e0015', 'Mark Thompson', 'United Kingdom', 'https://i.pravatar.cc/120?img=53', 5, 'Walking in Laikipia with a ranger was the highlight of 30 years of travel. Genuinely world-class guiding.', '00000000-0000-4000-8000-000000000314', 'published', false, 15),
  ('00000000-0000-4000-8000-0000000e0016', 'Sofia Lindgren', 'Norway', 'https://i.pravatar.cc/120?img=29', 4, 'Wonderful Zanzibar snorkelling and a lovely villa. One transfer was delayed but the team communicated well throughout.', '00000000-0000-4000-8000-000000000322', 'published', false, 16),
  ('00000000-0000-4000-8000-0000000e0017', 'Daniel & Rebecca Cohen', 'United States', 'https://i.pravatar.cc/120?img=14', 5, 'Uganda blew us away — gorillas, chimps and tree-climbing lions in one trip. Superbly organised and great value.', '00000000-0000-4000-8000-000000000319', 'published', true, 17),
  ('00000000-0000-4000-8000-0000000e0018', 'Chen Wei', 'Singapore', 'https://i.pravatar.cc/120?img=59', 5, 'The photography positioning was perfect — golden light, close sightings, and a guide who understood exactly what I needed.', '00000000-0000-4000-8000-000000000313', 'published', false, 18),
  ('00000000-0000-4000-8000-0000000e0019', 'Isabella Santos', 'Brazil', 'https://i.pravatar.cc/120?img=38', 5, 'Rwanda was extraordinary — the lodge, the gorillas, the people. I cried during the trek. Thank you Goldfinch.', '00000000-0000-4000-8000-000000000316', 'published', true, 19),
  ('00000000-0000-4000-8000-0000000e0020', 'Peter & Margaret Wilson', 'New Zealand', 'https://i.pravatar.cc/120?img=52', 5, 'Three generations travelled together and every age was catered for. A trip we will treasure forever.', '00000000-0000-4000-8000-000000000324', 'published', false, 20)
on conflict (id) do update set
  client_name = excluded.client_name, client_country = excluded.client_country, client_image_url = excluded.client_image_url,
  rating = excluded.rating, message = excluded.message, tour_id = excluded.tour_id, status = excluded.status,
  is_featured = excluded.is_featured, sort_order = excluded.sort_order;

