-- ---------- tours for the new experiences (so each experience has trips) ----------
insert into tours (id, title, slug, short_description, full_description, destination_id, category_id, experience_type, persona_tags,
  duration_days, duration_nights, budget_tier, price_from, currency, main_image_url, banner_image_url, highlights, difficulty_level,
  group_size_min, group_size_max, minimum_age, start_location, end_location, status, is_featured, is_popular, seo_title, meta_title, meta_description, created_by, updated_by)
values
  ('00000000-0000-4000-8000-000000000325', 'Great Migration Photography Safari', 'great-migration-photography-safari', 'Eight days built around light, access and the herds — for serious photographers.', 'A safari designed by and for photographers. We position you for golden-hour light, linger at sightings rather than rushing on, and use vehicles with space, bean bags and charging. Timed to the migration, you will have repeated chances at river crossings, predators and vast plains under dramatic skies, guided by someone who understands a photographer''s patience.', '00000000-0000-4000-8000-000000000101', '00000000-0000-4000-8000-000000000207', 'photography', array['solo','couple'], 8, 7, 'luxury', 4600, 'USD', 'https://images.unsplash.com/photo-1534177616072-ef7dc120449d', null, array['Golden-hour light','River crossings','Predator action','Vehicle space & bean bags'], 'Easy', 2, 4, 12, 'Kilimanjaro Airport', 'Arusha', 'published', false, true, 'Great Migration Photography Safari | Goldfinch Adventures', 'Great Migration Photography Safari', 'A photography-focused Serengeti migration safari built around the best light.', '00000000-0000-4000-8000-000000000001', '00000000-0000-4000-8000-000000000001'),
  ('00000000-0000-4000-8000-000000000326', 'Southern Tanzania Walking Safari', 'southern-tanzania-walking-safari', 'Six days on foot in the wild south — Ruaha and the Selous (Nyerere).', 'Leave the crowds behind in Tanzania''s vast, wild south. Led by armed, expert walking guides, you will track on foot through Ruaha and the Nyerere (Selous), reading signs and getting close to the smaller wonders most safaris miss, with boat safaris and classic game drives to complement the walks. Remote, authentic and deeply rewarding.', '00000000-0000-4000-8000-000000000101', '00000000-0000-4000-8000-000000000208', 'walking', array['solo','group'], 6, 5, 'mid_range', 3200, 'USD', 'https://images.unsplash.com/photo-1549366021-9f761d450615', null, array['Guided bush walks','Ruaha & Nyerere','Boat safaris','Remote wilderness'], 'Moderate', 2, 6, 16, 'Dar es Salaam', 'Dar es Salaam', 'published', false, false, 'Southern Tanzania Walking Safari | Goldfinch Adventures', 'Southern Tanzania Walking Safari', 'A walking safari in Tanzania''s wild south — Ruaha and the Nyerere (Selous).', '00000000-0000-4000-8000-000000000001', '00000000-0000-4000-8000-000000000001'),
  ('00000000-0000-4000-8000-000000000327', 'Northern Tanzania Cultural Journey', 'northern-tanzania-cultural-journey', 'Seven days blending wildlife with genuine cultural encounters.', 'A trip that puts people alongside wildlife. Alongside game drives in Tarangire and the Ngorongoro Crater, you will spend meaningful time with Maasai pastoralists and the Hadzabe — one of the last hunter-gatherer peoples on earth — through respectful, community-led visits. A richer, more human way to experience Tanzania.', '00000000-0000-4000-8000-000000000101', '00000000-0000-4000-8000-000000000209', 'cultural', array['couple','group'], 7, 6, 'mid_range', 3100, 'USD', 'https://images.unsplash.com/photo-1523805009345-7448845a9e53', null, array['Maasai & Hadzabe','Lake Eyasi','Ngorongoro Crater','Community-led visits'], 'Easy', 2, 8, 10, 'Arusha', 'Arusha', 'published', false, true, 'Northern Tanzania Cultural Journey | Goldfinch Adventures', 'Northern Tanzania Cultural Journey', 'A cultural safari blending wildlife with Maasai and Hadzabe encounters.', '00000000-0000-4000-8000-000000000001', '00000000-0000-4000-8000-000000000001'),
  ('00000000-0000-4000-8000-000000000328', 'Kenya Honeymoon Safari & Beach', 'kenya-honeymoon-safari-beach', 'Eight romantic days pairing the Mara with the Indian Ocean.', 'The perfect honeymoon. Begin with private game drives and candlelit dinners at an intimate Masai Mara camp, then fly to the palm-fringed Kenyan coast for barefoot beach days, a sunset dhow and total relaxation. Every detail is handled so you can simply be together.', '00000000-0000-4000-8000-000000000102', '00000000-0000-4000-8000-000000000210', 'beach', array['couple'], 8, 7, 'luxury', 5400, 'USD', 'https://images.unsplash.com/photo-1564760055775-d63b17a55c44', null, array['Intimate Mara camp','Diani beach','Candlelit dinners','Sunset dhow'], 'Easy', 2, 2, 18, 'Nairobi', 'Nairobi', 'published', false, true, 'Kenya Honeymoon Safari & Beach | Goldfinch Adventures', 'Kenya Honeymoon Safari & Beach', 'A romantic Kenya honeymoon pairing the Masai Mara with the coast.', '00000000-0000-4000-8000-000000000001', '00000000-0000-4000-8000-000000000001'),
  ('00000000-0000-4000-8000-000000000329', 'East Africa Family Adventure', 'east-africa-family-adventure', 'Seven days of safari designed around children.', 'Big adventure, gentle pace. This family safari keeps drives short and varied, chooses lodges with pools and family rooms, and weaves in hands-on moments — from spotting the Big Five to learning to throw a Maasai spear. Guides who genuinely love kids make all the difference.', '00000000-0000-4000-8000-000000000102', '00000000-0000-4000-8000-000000000211', 'safari', array['family'], 7, 6, 'mid_range', 3300, 'USD', 'https://images.unsplash.com/photo-1535941339077-2dd1c7963098', null, array['Kid-friendly pace','Family rooms & pools','Big Five','Hands-on learning'], 'Easy', 2, 8, 5, 'Nairobi', 'Nairobi', 'published', false, false, 'East Africa Family Adventure | Goldfinch Adventures', 'East Africa Family Adventure', 'A family safari in Kenya, paced and designed around children.', '00000000-0000-4000-8000-000000000001', '00000000-0000-4000-8000-000000000001'),
  ('00000000-0000-4000-8000-000000000330', 'Serengeti Calving Season Safari', 'serengeti-calving-season-safari', 'Six days in the southern Serengeti for the dramatic calving season.', 'From January to March, half a million wildebeest calves are born on the southern Serengeti plains in a matter of weeks — and the predators gather for the spectacle. This migration-focused safari puts you in the heart of the calving grounds for some of the most intense wildlife action of the year.', '00000000-0000-4000-8000-000000000101', '00000000-0000-4000-8000-000000000212', 'safari', array['couple','group'], 6, 5, 'mid_range', 3000, 'USD', 'https://images.unsplash.com/photo-1516426122078-c23e76319801', null, array['Calving season','Predator action','Southern Serengeti','Ndutu plains'], 'Easy', 2, 6, 8, 'Arusha', 'Arusha', 'published', false, true, 'Serengeti Calving Season Safari | Goldfinch Adventures', 'Serengeti Calving Season Safari', 'A southern Serengeti calving-season migration safari (Jan–Mar).', '00000000-0000-4000-8000-000000000001', '00000000-0000-4000-8000-000000000001')
on conflict (id) do update set
  title = excluded.title, slug = excluded.slug, short_description = excluded.short_description, full_description = excluded.full_description,
  destination_id = excluded.destination_id, category_id = excluded.category_id, experience_type = excluded.experience_type, persona_tags = excluded.persona_tags,
  duration_days = excluded.duration_days, duration_nights = excluded.duration_nights, budget_tier = excluded.budget_tier, price_from = excluded.price_from,
  currency = excluded.currency, main_image_url = excluded.main_image_url, highlights = excluded.highlights, difficulty_level = excluded.difficulty_level,
  group_size_min = excluded.group_size_min, group_size_max = excluded.group_size_max, minimum_age = excluded.minimum_age,
  start_location = excluded.start_location, end_location = excluded.end_location, status = excluded.status,
  is_featured = excluded.is_featured, is_popular = excluded.is_popular, seo_title = excluded.seo_title, meta_title = excluded.meta_title, meta_description = excluded.meta_description;

-- ---------- itineraries for the new-experience tours (325–330) ----------
insert into itinerary_days (tour_id, day_number, title, description, accommodation, meals, activities)
values
  -- 325 Great Migration Photography Safari (Tanzania)
  ('00000000-0000-4000-8000-000000000325', 1, 'Arrive & transfer to the Serengeti', 'Met at Kilimanjaro Airport and flown into the Serengeti to start shooting the same afternoon.', 'Luxury tented camp', 'Lunch, Dinner', 'Arrival, afternoon photo drive'),
  ('00000000-0000-4000-8000-000000000325', 2, 'Golden-hour predators', 'Dawn and dusk drives positioned for the best light on lion, cheetah and leopard.', 'Luxury tented camp', 'Breakfast, Lunch, Dinner', 'Two photo drives'),
  ('00000000-0000-4000-8000-000000000325', 3, 'Following the herds', 'Track the migration columns for action and big skies.', 'Luxury tented camp', 'Breakfast, Lunch, Dinner', 'Full-day photo drive'),
  ('00000000-0000-4000-8000-000000000325', 4, 'River crossings', 'Position at the river for the dramatic crossings (seasonal).', 'Luxury tented camp', 'Breakfast, Lunch, Dinner', 'Crossing watch, photo drive'),
  ('00000000-0000-4000-8000-000000000325', 5, 'Balloon & bush breakfast', 'A sunrise balloon flight for aerial shots, then a champagne breakfast.', 'Luxury tented camp', 'Breakfast, Lunch, Dinner', 'Balloon flight, photo drive'),
  ('00000000-0000-4000-8000-000000000325', 6, 'Depart', 'A final golden-hour drive before flying out.', 'n/a', 'Breakfast', 'Departure transfer'),
  -- 326 Southern Tanzania Walking Safari
  ('00000000-0000-4000-8000-000000000326', 1, 'Arrive Dar & fly to Nyerere', 'Connect by light aircraft into the wild south.', 'Tented camp', 'Lunch, Dinner', 'Arrival, sundowner'),
  ('00000000-0000-4000-8000-000000000326', 2, 'First bush walk', 'Out on foot with an armed guide, learning tracks and signs.', 'Tented camp', 'Breakfast, Lunch, Dinner', 'Walking safari, boat safari'),
  ('00000000-0000-4000-8000-000000000326', 3, 'Rufiji River', 'A boat safari among hippo and crocs, then an afternoon walk.', 'Tented camp', 'Breakfast, Lunch, Dinner', 'Boat safari, walk'),
  ('00000000-0000-4000-8000-000000000326', 4, 'Transfer to Ruaha', 'Fly to remote Ruaha for big herds and predators.', 'Tented camp', 'Breakfast, Lunch, Dinner', 'Transfer, game drive'),
  ('00000000-0000-4000-8000-000000000326', 5, 'Ruaha on foot', 'Walking and driving in one of Africa''s wildest parks.', 'Tented camp', 'Breakfast, Lunch, Dinner', 'Walking safari, game drive'),
  ('00000000-0000-4000-8000-000000000326', 6, 'Depart', 'Fly back to Dar for your onward flight.', 'n/a', 'Breakfast', 'Departure transfer'),
  -- 327 Northern Tanzania Cultural Journey (the opened tour)
  ('00000000-0000-4000-8000-000000000327', 1, 'Arrive Kilimanjaro & Arusha', 'Met on arrival and transferred to Arusha for a relaxed overnight and trip briefing.', 'Arusha lodge', 'Dinner', 'Arrival transfer, briefing'),
  ('00000000-0000-4000-8000-000000000327', 2, 'Tarangire National Park', 'A full day among Tarangire''s giant baobabs and famous elephant herds.', 'Safari lodge', 'Breakfast, Lunch, Dinner', 'Game drive'),
  ('00000000-0000-4000-8000-000000000327', 3, 'Lake Eyasi & the Hadzabe', 'A dawn with the Hadzabe hunter-gatherers, then meet Datoga blacksmiths — a rare, respectful cultural encounter.', 'Lake Eyasi camp', 'Breakfast, Lunch, Dinner', 'Hadzabe & Datoga visits'),
  ('00000000-0000-4000-8000-000000000327', 4, 'Karatu & Maasai community', 'Visit a coffee farm and spend meaningful time with a Maasai community.', 'Karatu lodge', 'Breakfast, Lunch, Dinner', 'Coffee farm, Maasai village'),
  ('00000000-0000-4000-8000-000000000327', 5, 'Ngorongoro Crater', 'Descend into the crater for an extraordinary full day of wildlife.', 'Crater-rim lodge', 'Breakfast, Lunch, Dinner', 'Full-day crater game drive'),
  ('00000000-0000-4000-8000-000000000327', 6, 'Mto wa Mbu cultural day', 'A guided village and market walk — farming, crafts and local life.', 'Lake Manyara lodge', 'Breakfast, Lunch, Dinner', 'Village & market walk'),
  ('00000000-0000-4000-8000-000000000327', 7, 'Depart Arusha', 'A leisurely morning before your departure transfer.', 'n/a', 'Breakfast', 'Departure transfer'),
  -- 328 Kenya Honeymoon Safari & Beach
  ('00000000-0000-4000-8000-000000000328', 1, 'Arrive Nairobi', 'Welcome to Kenya; overnight at a boutique hotel.', 'Nairobi hotel', 'Dinner', 'Arrival transfer'),
  ('00000000-0000-4000-8000-000000000328', 2, 'Fly to the Masai Mara', 'Into an intimate camp for your first romantic game drive.', 'Mara tented camp', 'Breakfast, Lunch, Dinner', 'Game drive'),
  ('00000000-0000-4000-8000-000000000328', 3, 'Mara & private dining', 'Big-cat country by day, a candlelit dinner by night.', 'Mara tented camp', 'Breakfast, Lunch, Dinner', 'Game drives, private dinner'),
  ('00000000-0000-4000-8000-000000000328', 4, 'Fly to the coast', 'Transfer to the palm-fringed Kenyan coast.', 'Beach resort', 'Breakfast', 'Flight, beach time'),
  ('00000000-0000-4000-8000-000000000328', 5, 'Diani beach days', 'Relax, snorkel and enjoy a sunset dhow.', 'Beach resort', 'Breakfast', 'Beach, dhow cruise'),
  ('00000000-0000-4000-8000-000000000328', 6, 'Depart', 'A final beach morning before flying home.', 'n/a', 'Breakfast', 'Departure transfer'),
  -- 329 East Africa Family Adventure
  ('00000000-0000-4000-8000-000000000329', 1, 'Arrive Nairobi', 'Family-friendly welcome and overnight.', 'Nairobi hotel', 'Dinner', 'Arrival, giraffe centre'),
  ('00000000-0000-4000-8000-000000000329', 2, 'Fly to the Mara', 'Short flight and a gentle first game drive.', 'Family tented camp', 'Breakfast, Lunch, Dinner', 'Game drive'),
  ('00000000-0000-4000-8000-000000000329', 3, 'Mara for families', 'Short, fun drives with hands-on learning for the kids.', 'Family tented camp', 'Breakfast, Lunch, Dinner', 'Game drive, Maasai visit'),
  ('00000000-0000-4000-8000-000000000329', 4, 'Lake Nakuru', 'Flamingos and rhino at a compact, rewarding park.', 'Lakeside lodge', 'Breakfast, Lunch, Dinner', 'Game drive'),
  ('00000000-0000-4000-8000-000000000329', 5, 'Depart', 'Return to Nairobi for your departure.', 'n/a', 'Breakfast', 'Departure transfer'),
  -- 330 Serengeti Calving Season Safari
  ('00000000-0000-4000-8000-000000000330', 1, 'Arrive & transfer to Ndutu', 'Into the southern Serengeti calving grounds.', 'Mobile camp', 'Lunch, Dinner', 'Arrival, afternoon drive'),
  ('00000000-0000-4000-8000-000000000330', 2, 'Calving on the plains', 'Witness thousands of births and the predators that follow.', 'Mobile camp', 'Breakfast, Lunch, Dinner', 'Full-day game drive'),
  ('00000000-0000-4000-8000-000000000330', 3, 'Predator action', 'Cheetah and lion hunts across the open short-grass plains.', 'Mobile camp', 'Breakfast, Lunch, Dinner', 'Two game drives'),
  ('00000000-0000-4000-8000-000000000330', 4, 'Ngorongoro Crater', 'A full day in the wildlife-packed crater.', 'Crater-rim lodge', 'Breakfast, Lunch, Dinner', 'Crater game drive'),
  ('00000000-0000-4000-8000-000000000330', 5, 'Depart Arusha', 'Drive to Arusha for your departure.', 'n/a', 'Breakfast', 'Departure transfer')
on conflict (tour_id, day_number) do update set
  title = excluded.title, description = excluded.description, accommodation = excluded.accommodation, meals = excluded.meals, activities = excluded.activities;
